const quote = $input.first().json;
const itemsList = typeof quote.items === 'string' ? JSON.parse(quote.items) : quote.items;
const itemsSummary = itemsList.map(item => `• *${item.product}*: ${item.quantity} x ${Number(item.unit_price).toLocaleString('vi-VN')} đ`).join('\n');

const slackPayload = {
  text: `Yêu cầu phê duyệt báo giá: #${quote.id.slice(0, 8).toUpperCase()}`,
  blocks: [
    {
      type: "header",
      text: {
        type: "plain_text",
        text: "🔔 YÊU CẦU DUYỆT BÁO GIÁ MỚI",
        emoji: true
      }
    },
    {
      type: "section",
      fields: [
        { type: "mrkdwn", text: `*Khách hàng:*\n${quote.customer_name}` },
        { type: "mrkdwn", text: `*Công ty:*\n${quote.company_name || 'N/A'}` },
        { type: "mrkdwn", text: `*Tổng tiền:*\n*${Number(quote.total_amount).toLocaleString('vi-VN')} đ*` },
        { type: "mrkdwn", text: `*Chiết khấu:*\n${quote.discount_percent}%` }
      ]
    },
    {
      type: "section",
      text: {
        type: "mrkdwn",
        text: `*Danh mục sản phẩm:*\n${itemsSummary}`
      }
    },
    {
      type: "actions",
      elements: [
        {
          type: "button",
          text: { type: "plain_text", text: "✅ Phê duyệt (Approve)", emoji: true },
          style: "primary",
          value: JSON.stringify({ action: "APPROVED", quote_id: quote.id })
        },
        {
          type: "button",
          text: { type: "plain_text", text: "❌ Từ chối (Reject)", emoji: true },
          style: "danger",
          value: JSON.stringify({ action: "REJECTED", quote_id: quote.id })
        }
      ]
    }
  ]
};

return [{ json: { slackPayload, quote_id: quote.id } }];

let rawPayload = $input.first().json.body.payload;

// Nếu dữ liệu gửi dạng string từ Slack thì parse ra JSON
let data = typeof rawPayload === 'string' ? JSON.parse(rawPayload) : (rawPayload || $input.first().json.body);

// Lấy thông tin từ nút bấm đã gắn ở Bước 2
let selectedAction = "APPROVED";
let quoteId = "";
let managerName = data.user ? (data.user.name || data.user.username) : "Slack Manager";

if (data.actions && data.actions.length > 0) {
  const valueObj = JSON.parse(data.actions[0].value);
  selectedAction = valueObj.action;
  quoteId = valueObj.quote_id;
} else if (data.quote_id) {
  // Dự phòng khi gọi API test thẳng qua curl/Postman
  quoteId = data.quote_id;
  selectedAction = data.action || "APPROVED";
}

return [{
  json: {
    quote_id: quoteId,
    approval_status: selectedAction,
    approved_by: managerName,
    message: `Đã cập nhật trạng thái báo giá sang ${selectedAction}`
  }
}];
